// Scienze umane, metodologia, organizzazione e discipline di base per il corso di laurea in Infermieristica.
// Sintesi didattiche: per l'esame vale il programma del docente e il testo in adozione.
const C = (id, title, aliases, cat, summary, s, rel = [], src = []) => ({ id, type: 'care', title, aliases, cat, summary, sections: { cos: s }, rel, sources: ['textbooks', ...src], rev: '2026-10', v: '1.0', verify: true });

export default [
  // ------------------------------------------------------------------ PSICOLOGIA, SOCIOLOGIA, PEDAGOGIA
  C('psicologia-relazione-aiuto', 'Psicologia, comunicazione e relazione d’aiuto', ['relazione d’aiuto', 'comunicazione efficace', 'ascolto attivo', 'empatia', 'comunicazione non verbale', 'cattive notizie', 'SPIKES', 'Peplau', 'Rogers', 'Kübler-Ross', 'coping', 'stress', 'assertività', 'colloquio'], 'Scienze umane', 'La relazione è lo strumento di lavoro dell’infermiere: comunicare bene, ascoltare e riconoscere le emozioni di paziente e famiglia fa parte della cura.',
    [{ h: 'Comunicazione' }, ['**Assiomi di Watzlawick**: non si può non comunicare; ogni comunicazione ha un contenuto e una relazione; la comunicazione è verbale, non verbale (sguardo, postura, tono, distanza) e para-verbale.', '**Ascolto attivo**: attenzione piena, silenzi, riformulazione, domande aperte, sintesi; **empatia** = comprendere e riconoscere l’emozione dell’altro senza confondersi con essa (diversa dalla simpatia).', 'Barriere: giudizio, consigli non richiesti, rassicurazioni premature, interrompere, gergo tecnico, fretta, rumore e mancanza di privacy.', '**Assertività**: esprimere bisogni e limiti in modo chiaro e rispettoso (stili: passivo, aggressivo, assertivo).'],
      { h: 'Relazione d’aiuto' }, ['**Carl Rogers**: accoglienza incondizionata, congruenza, comprensione empatica.', '**Hildegard Peplau**: relazione terapeutica in fasi (orientamento, identificazione, sfruttamento, risoluzione); l’infermiere ha ruoli di estraneo, risorsa, insegnante, guida, sostituto, consulente.', 'Evitare la **sovra-identificazione** e il **distacco**: serve una “giusta distanza” e supervisione.'],
      { h: 'Comunicare cattive notizie (protocollo SPIKES)' }, [{ ol: ['**S**etting: luogo riservato, tempo, sedersi, spegnere il cellulare.', '**P**erception: chiedere cosa la persona sa e capisce.', '**I**nvitation: chiedere quanto vuole sapere.', '**K**nowledge: dare informazioni con frasi brevi e chiare, a piccole dosi.', '**E**motions: riconoscere e nominare le emozioni (“Capisco che è un colpo difficile”).', '**S**trategy & summary: piano condiviso e sintesi.'] }, 'La comunicazione della diagnosi spetta al **medico**; l’infermiere accoglie, sostiene, chiarisce e riferisce bisogni ed emozioni all’équipe.'],
      { h: 'Stress, coping e fasi del lutto' }, ['**Stress** (Selye): sindrome generale di adattamento in tre fasi: allarme, resistenza, esaurimento. **Coping** (Lazarus e Folkman): centrato sul problema o sull’emozione.', '**Kübler-Ross** (non lineari): negazione, rabbia, contrattazione, depressione, accettazione. Il lutto è un processo individuale; supporto, ascolto, rituali.', '**Meccanismi di difesa** (Freud e successivi): negazione, regressione, proiezione, razionalizzazione, spostamento, rimozione: li incontri nei pazienti e in te.'],
      { h: 'Operatore sanitario' }, ['Burnout (Maslach): esaurimento emotivo, depersonalizzazione, ridotta realizzazione; prevenzione con supporto di équipe, supervisione, pause, formazione ([[sicurezza-operatore]]).']],
    ['educazione-terapeutica', 'cure-palliative', 'sicurezza-operatore', 'disturbi-ansia', 'sviluppo-infanzia-crescita', 'codice-deontologico']),

  C('sociologia-antropologia-salute', 'Sociologia e antropologia della salute, migrazione e cultura', ['determinanti sociali della salute', 'disuguaglianze di salute', 'stigma', 'ruolo del malato', 'Parsons', 'transcultural nursing', 'Leininger', 'mediazione culturale', 'immigrazione', 'STP', 'medicina narrativa', 'malattia e disease illness sickness', 'famiglia'], 'Scienze umane', 'La salute dipende da condizioni sociali, economiche e culturali; capirle aiuta a evitare discriminazioni e ad assistere persone con background diversi.',
    [{ h: 'Salute e società' }, ['**Determinanti sociali** (OMS): reddito, istruzione, lavoro, abitazione, reti sociali, accesso ai servizi; generano **disuguaglianze di salute** (gradiente sociale).', '**Disease** (malattia come processo biologico), **illness** (esperienza soggettiva), **sickness** (ruolo sociale della malattia).', '**Ruolo del malato** (Parsons): esenzione da alcune responsabilità, obbligo di cercare aiuto e collaborare. **Stigma** (Goffman): attributo screditante che isola (es. HIV, salute mentale, obesità).', '**Famiglia**: sistema che cambia (nucleare, allargata, monogenitoriale, ricostituita); il caregiver familiare è risorsa e “paziente nascosto”.'],
      { h: 'Cultura e migrazione' }, ['**Assistenza transculturale** (Leininger): rispettare credenze, alimentazione, pudore, ruoli di genere, riti del fine vita; evitare stereotipi (la cultura è dinamica e individuale).', '**Mediazione linguistico-culturale** e interpreti professionisti (non i figli minorenni); consenso informato in lingua comprensibile.', '**Diritti in Italia**: assistenza sanitaria urgente e essenziale anche per i non regolari con codice **STP** (stranieri temporaneamente presenti), senza segnalazione all’autorità; iscrizione al SSN per i regolarmente soggiornanti.', 'Pratiche culturali critiche: **mutilazioni genitali femminili** (vietate dalla L. 7/2006), matrimoni forzati: vedi [[violenza-maltrattamento]].'],
      { h: 'Medicina narrativa' }, ['Raccogliere le storie di malattia migliora relazione, adesione alle cure ed esiti (legge 38/2010 sul dolore e linee di indirizzo sulla medicina narrativa).']],
    ['psicologia-relazione-aiuto', 'violenza-maltrattamento', 'assistenza-territoriale', 'igiene-sanita-pubblica', 'codice-deontologico']),

  C('educazione-terapeutica', 'Educazione terapeutica e promozione della salute', ['educazione sanitaria', 'health literacy', 'teach-back', 'empowerment', 'adesione terapeutica', 'aderenza', 'colloquio motivazionale', 'stadi del cambiamento', 'Prochaska', 'apprendimento adulto', 'Knowles', 'Carta di Ottawa', 'promozione della salute', 'self-management'], 'Scienze umane', 'Educare il paziente (e il caregiver) è una competenza infermieristica centrale: si impara meglio quando l’informazione è comprensibile, pratica e condivisa.',
    [{ h: 'Principi' }, ['**Educazione sanitaria**: informare; **educazione terapeutica**: rendere il paziente cronico capace di gestire la malattia (autogestione); **promozione della salute** (Carta di Ottawa 1986): processo che mette le persone in grado di aumentare il controllo sulla propria salute.', '**Health literacy**: capacità di trovare, capire e usare le informazioni sanitarie; molte persone ne hanno una limitata. Usa parole semplici, immagini, poche informazioni per volta.', '**Apprendimento dell’adulto** (Knowles): ha bisogno di sapere perché, parte dall’esperienza, impara su problemi concreti.', '**Domini di apprendimento** (Bloom): cognitivo (sapere), affettivo (atteggiamenti), psicomotorio (saper fare).'],
      { h: 'Metodo' }, [{ ol: ['**Valuta** bisogni, conoscenze, credenze, barriere (lingua, vista, udito, cognitività, motivazione).', '**Definisci obiettivi** condivisi, specifici e realistici.', '**Insegna** con dimostrazione e pratica; usa il **teach-back** (“Mi spiega con parole sue come userà la penna?”).', '**Rinforza** con materiale scritto semplice e contatti utili.', '**Valuta e documenta** cosa il paziente ha capito e sa fare.'] }],
      { h: 'Cambiare comportamento' }, ['**Stadi del cambiamento** (Prochaska e DiClemente): precontemplazione, contemplazione, preparazione, azione, mantenimento (e ricadute normali).', '**Colloquio motivazionale**: domande aperte, ascolto riflessivo, valorizzare le motivazioni della persona, evitare di “convincere” (ambivalenza).', '**Aderenza terapeutica**: ostacoli frequenti sono costo, effetti collaterali, complessità, scarsa comprensione, sfiducia; semplificare gli schemi e coinvolgere il paziente.'],
      { h: 'Esempi nell’app' }, ['[[penna-insulina]], [[diabete-mellito]], [[calendario-vaccinale]], [[ist-panoramica]] (counselling non giudicante), [[accoglienza-dimissione]].']],
    ['psicologia-relazione-aiuto', 'penna-insulina', 'accoglienza-dimissione', 'gestione-inefficace-regime-terapeutico', 'conoscenza-deficitaria']),

  C('teorie-infermieristiche', 'Teorie e modelli concettuali dell’infermieristica', ['Nightingale', 'Orem', 'Roy', 'Neuman', 'Watson', 'Benner', 'Leininger', 'Peplau', 'Henderson', 'Maslow', 'metaparadigma', 'autocura', 'modello di adattamento', 'caring', 'da novizio a esperto', 'Johnson', 'Rogers'], 'Fondamenti dell’infermieristica', 'I modelli concettuali spiegano che cosa è l’assistenza infermieristica e guidano accertamento e pianificazione: ogni teorico mette l’accento su un aspetto diverso.',
    [{ h: 'Metaparadigma infermieristico' }, ['Quattro concetti comuni: **persona**, **ambiente**, **salute**, **assistenza infermieristica**.'],
      { h: 'Principali teorie' }, [{ table: { head: ['Autore', 'Idea centrale', 'Parole chiave'], rows: [['**Florence Nightingale** (1860)', 'L’infermiere crea l’ambiente che permette alla natura di guarire', 'Igiene, aria, luce, rumore, dieta, osservazione; statistica sanitaria'], ['**Virginia Henderson** (1960)', 'Aiutare la persona a svolgere le attività che contribuiscono alla salute finché può farle da sola ([[henderson-bisogni]])', '14 bisogni fondamentali, indipendenza'], ['**Dorothea Orem**', 'Il paziente ha un deficit di **autocura**: l’infermiere compensa in modo totale, parziale o con supporto-educazione', 'Autocura, sistemi di cura, deficit'], ['**Callista Roy**', 'La persona si **adatta** ai cambiamenti con stimoli focali, contestuali e residui', 'Modelli di adattamento: fisiologico, concetto di sé, ruolo, interdipendenza'], ['**Betty Neuman**', 'Persona come sistema che difende sé stesso da stressori con linee di resistenza', 'Prevenzione primaria, secondaria, terziaria'], ['**Hildegard Peplau**', 'L’assistenza è un processo interpersonale terapeutico', 'Relazione, fasi, ruoli ([[psicologia-relazione-aiuto]])'], ['**Jean Watson**', 'La cura (**caring**) è l’essenza: relazione umana, presenza, dimensione spirituale', 'Caring, fattori di carità'], ['**Madeleine Leininger**', 'La cura è influenzata dalla cultura', 'Transcultural nursing ([[sociologia-antropologia-salute]])'], ['**Patricia Benner**', 'Si cresce professionalmente da principiante a esperto', 'Novizio, principiante avanzato, competente, abile, esperto'], ['**Marjory Gordon**', 'Valutazione per modelli funzionali di salute', '11 modelli ([[gordon-modelli]])'], ['**Abraham Maslow**', 'Piramide dei bisogni (non è una teoria infermieristica ma è molto usata)', 'Fisiologici, sicurezza, appartenenza, stima, autorealizzazione']] } }],
      { h: 'Come si usano' }, ['Il modello scelto dal servizio orienta l’**accertamento** ([[accertamento-infermieristico]]) e il **processo infermieristico** ([[processo-infermieristico]]); diagnosi NANDA-I, NOC e NIC danno un linguaggio standard (solo titoli indicativi nell’app: [[diagnosi-infermieristiche-guida]]).']],
    ['henderson-bisogni', 'gordon-modelli', 'processo-infermieristico', 'accertamento-infermieristico', 'diagnosi-infermieristiche-guida']),

  // ------------------------------------------------------------------ ETICA, DIRITTO, MANAGEMENT
  C('bioetica', 'Bioetica e deontologia: principi, dilemmi e metodo', ['bioetica', 'principi di Beauchamp e Childress', 'autonomia', 'beneficenza', 'non maleficenza', 'giustizia', 'dilemma etico', 'comitato etico', 'Convenzione di Oviedo', 'Dichiarazione di Helsinki', 'eutanasia', 'suicidio assistito', 'accanimento terapeutico', 'sedazione palliativa', 'obiezione di coscienza', 'sperimentazione clinica', 'Codice ICN'], 'Etica e diritto', 'La bioetica aiuta a decidere quando i valori entrano in conflitto: ci sono principi condivisi, un metodo per ragionare e norme che li traducono in diritti e doveri.',
    [{ h: 'I quattro principi (Beauchamp e Childress)' }, [{ ul: ['**Autonomia**: rispetto della capacità di decidere della persona (consenso, rifiuto, DAT).', '**Beneficenza**: fare il bene del paziente.', '**Non maleficenza**: non nuocere (“primum non nocere”).', '**Giustizia**: distribuire equamente risorse e cure, senza discriminazioni.'] }, 'Altri concetti: **dignità**, **vulnerabilità**, **responsabilità**, **solidarietà**, **veridicità**, **fedeltà**, **riservatezza**.'],
      { h: 'Metodo per un dilemma etico' }, [{ ol: ['Riconosci il problema e i valori in conflitto.', 'Raccogli i fatti clinici, i desideri del paziente, la normativa e le risorse.', 'Individua le opzioni e le conseguenze di ciascuna.', 'Confrontale con i principi e con il codice deontologico.', 'Decidi con l’équipe (e il comitato etico se serve) e documenta.', 'Rivaluta l’esito.'] }],
      { h: 'Documenti e norme' }, ['**Codice di Norimberga** (1947) e **Dichiarazione di Helsinki** (Associazione Medica Mondiale, 1964, rivista più volte): etica della sperimentazione sull’uomo; **Rapporto Belmont** (1979); **Convenzione di Oviedo** (1997) su diritti umani e biomedicina.', '**Codice ICN** (International Council of Nurses) per le infermiere e **Codice deontologico FNOPI** ([[codice-deontologico]]).', '**L. 219/2017** ([[consenso-dat]]): consenso, rifiuto, DAT, pianificazione condivisa, sedazione palliativa profonda; condanna l’ostinazione irragionevole.', 'Fine vita in Italia: **eutanasia** e aiuto attivo a morire sono reati (artt. 575, 579, 580 c.p.); la Corte costituzionale (sentenza 242/2019) ha reso non punibile in condizioni rigorose l’aiuto al suicidio, con verifica del SSN e parere del comitato etico territoriale; le regole sono in evoluzione (verificare la normativa vigente).', '**Sperimentazione clinica**: consenso scritto, **comitato etico**, protezione dei dati, nessuna pressione sul paziente.', '**Trapianti**: donazione volontaria e gratuita, consenso o dissenso espresso, accertamento della morte rigoroso ([[trapianti-donazione]]).'],
      { h: 'Conflitti tipici' }, ['Rifiuto di cure salvavita (Testimoni di Geova e trasfusioni); paziente incapace senza DAT (fiduciario, amministratore di sostegno); informare la famiglia contro la volontà del paziente (no: segreto professionale); risorse limitate (triage); obiezione di coscienza ([[aborto-ivg]]).']],
    ['codice-deontologico', 'consenso-dat', 'privacy-segreto', 'cure-palliative', 'trapianti-donazione', 'medicina-legale-diritto']),

  C('medicina-legale-diritto', 'Medicina legale e diritto per l’infermiere', ['medicina legale', 'diritto sanitario', 'responsabilità penale', 'omissione di soccorso', 'lesioni personali', 'omicidio colposo', 'falso ideologico', 'pubblico ufficiale', 'incaricato di pubblico servizio', 'esercizio abusivo della professione', 'cartella clinica valore giuridico', 'denuncia', 'referto', 'nesso di causalità', 'colpa', 'dolo', 'imperizia', 'imprudenza', 'negligenza', 'posizione di garanzia', 'certificato di morte', 'accertamento di morte'], 'Etica e diritto', 'Le norme fondamentali che un infermiere deve conoscere: tipi di responsabilità, reati più frequenti in ambito sanitario, documentazione con valore legale e obblighi di denuncia.',
    [{ h: 'Tre responsabilità' }, ['**Penale** (personale: per un reato come lesioni o omicidio colposo, omissione di soccorso, rivelazione di segreto); **civile** (risarcimento del danno: contrattuale per la struttura, extracontrattuale per il singolo operatore: [[responsabilita-professionale]]); **disciplinare** (azienda: CCNL; Ordine professionale OPI: [[codice-deontologico]]); in più la **responsabilità amministrativo-contabile** per i dipendenti pubblici (danno erariale).'],
      { h: 'Elementi del reato colposo' }, ['**Colpa**: negligenza (trascuratezza), imprudenza (azione avventata), imperizia (mancanza di abilità), inosservanza di leggi e regolamenti. **Dolo**: volontà dell’evento.', '**Nesso di causalità**: l’evento deve essere conseguenza dell’azione o omissione; **posizione di garanzia**: chi ha il dovere giuridico di proteggere un bene (l’infermiere verso il paziente in carico) risponde dell’evento che non impedisce.', 'Reati tipici: lesioni personali colpose (art. 590), omicidio colposo (589), omissione di soccorso (593) e di atti d’ufficio (328), rivelazione di segreto professionale (622), falsità ideologica in atto pubblico (479) e in certificati (480–481), abbandono di persone minori o incapaci (591), violenza privata (610: es. contenzione senza giustificazione), esercizio abusivo di una professione (348).'],
      { h: 'Qualifica giuridica e obblighi di denuncia' }, ['L’infermiere dipendente pubblico è **pubblico ufficiale o incaricato di pubblico servizio** secondo le funzioni; ha obbligo di **denuncia** (art. 361–362 c.p.) dei reati procedibili d’ufficio conosciuti nell’esercizio delle funzioni e di **referto** (art. 365) per i casi che possono presentare i caratteri di un delitto; vedi [[privacy-segreto]].', 'I **certificati** (morte, infortunio) e la **cartella clinica** sono atti con valore di **fede privilegiata** (atto pubblico): firma, data e ora, leggibilità, niente cancellature con correttore ([[documentazione-infermieristica]]). La cartella appartiene alla struttura; il paziente ha diritto di accesso (L. 241/1990, L. 24/2017).'],
      { h: 'Morte' }, ['L’**accertamento di morte** (cerebrale con criteri della L. 578/1993 e DM 11/04/2008 aggiornato; cardiaca con ECG di almeno 20 minuti secondo normativa) e la **constatazione** spettano al medico; periodo di osservazione e regole di polizia mortuaria ([[cure-palliative]], [[trapianti-donazione]]).'],
      { h: 'Medicina legale e assicurazione' }, ['**Danno biologico** (lesione dell’integrità psicofisica), invalidità civile, infortunio sul lavoro (INAIL), malattia professionale (es. punture accidentali, allergia al lattice, patologie muscolo-scheletriche: [[sicurezza-operatore]]).']],
    ['responsabilita-professionale', 'privacy-segreto', 'consenso-dat', 'documentazione-infermieristica', 'bioetica', 'violenza-maltrattamento']),

  C('management-organizzazione', 'Management, organizzazione e qualità dell’assistenza', ['modelli organizzativi', 'primary nursing', 'case management', 'team nursing', 'intensità di cura', 'complessità assistenziale', 'turni', 'delega', 'leadership', 'coordinatore infermieristico', 'ciclo di Deming', 'PDCA', 'audit clinico', 'indicatori di qualità', 'accreditamento', 'percorsi diagnostico terapeutici', 'PDTA', 'lean', 'burnout organizzativo', 'carico di lavoro', 'dotazioni organiche', 'rapporto infermiere paziente', 'skill mix', 'Magnet'], 'Organizzazione', 'Come si organizza il lavoro infermieristico nei servizi: modelli, turni, delega, qualità e miglioramento continuo.',
    [{ h: 'Modelli organizzativi dell’assistenza' }, [{ table: { head: ['Modello', 'Caratteristiche'], rows: [['**Funzionale** (per compiti)', 'Ogni operatore svolge un compito per tutti i pazienti (terapia, igiene…); efficiente ma frammentato'], ['**Per piccole équipe (team nursing)**', 'Gruppo di infermieri e OSS assegnato a un gruppo di pazienti'], ['**Primary nursing**', 'Un infermiere “primario” è responsabile del piano assistenziale di pochi pazienti dall’ingresso alla dimissione, 24 ore su 24; massima continuità'], ['**Case management**', 'Gestione di casi complessi lungo il percorso tra ospedale e territorio'], ['**Per intensità di cura**', 'Pazienti raggruppati per complessità assistenziale (e non per specialità): aree a bassa, media, alta intensità']] } }],
      { h: 'Risorse e turni' }, ['**Fabbisogno di personale**: dipende da numero di pazienti, complessità assistenziale, tempi di assistenza e skill mix infermieri/OSS; **rapporto infermiere/paziente** più basso è associato a esiti migliori (meno mortalità e cadute).', 'I turni coprono le 24 ore (mattina, pomeriggio, notte) nel rispetto del riposo obbligatorio (D.Lgs. 66/2003: almeno 11 ore consecutive di riposo ogni 24 ore e pause).', '**Delega**: l’infermiere può attribuire attività a personale di supporto (OSS) restando responsabile di pianificazione e verifica; si delega il **compito**, non la responsabilità; l’attività deve essere nelle competenze di chi la riceve.'],
      { h: 'Leadership e gruppo di lavoro' }, ['Stili di leadership (autoritario, democratico, laissez-faire; situazionale), motivazione (Maslow, Herzberg), gestione dei conflitti (negoziazione), riunioni efficaci, feedback.', '**Coordinatore** infermieristico: organizza, valuta, gestisce risorse e qualità; **dirigente** delle professioni sanitarie a livello aziendale.'],
      { h: 'Qualità e miglioramento' }, ['**Ciclo PDCA** (Plan, Do, Check, Act): pianificare, fare, verificare, agire; **audit clinico**: confronto della pratica con standard; **indicatori** di struttura, processo ed esito (es. cadute per 1000 giornate di degenza, prevalenza di lesioni da pressione, infezioni).', '**Accreditamento** istituzionale (requisiti minimi obbligatori) e certificazione di qualità (ISO 9001); **PDTA**: percorso diagnostico-terapeutico assistenziale condiviso per una patologia ([[assistenza-territoriale]]).', '**Sicurezza**: gestione del rischio clinico, segnalazione degli eventi ([[rischio-clinico]]).'],
      { h: 'Organizzazione del SSN' }, ['Vedi [[ssn-organizzazione]]: livelli di governo, ASL, distretti, ospedali, finanziamento.']],
    ['ssn-organizzazione', 'rischio-clinico', 'profilo-normativo', 'documentazione-infermieristica', 'assistenza-territoriale', 'accoglienza-dimissione'], ['who-ps', 'dm77-2022']),

  C('ssn-organizzazione', 'Servizio Sanitario Nazionale: organizzazione, LEA e finanziamento', ['SSN', 'ASL', 'AUSL', 'Azienda USL Toscana centro', 'AOU Careggi', 'distretto sanitario', 'dipartimento', 'LEA', 'livelli essenziali di assistenza', 'DRG', 'ticket', 'esenzioni', 'legge 833', 'D.Lgs. 502', 'Regione Toscana', 'medico di medicina generale', 'pediatra di libera scelta', 'guardia medica', 'continuità assistenziale', 'Case della Comunità', 'azienda ospedaliero-universitaria'], 'Organizzazione', 'Il SSN italiano è universalistico: garantisce a tutti i livelli essenziali di assistenza ed è organizzato per Stato, Regioni e Aziende sanitarie.',
    [{ h: 'Storia e principi' }, ['**L. 833/1978**: istituzione del SSN (universalità, uguaglianza, equità, finanziamento con la fiscalità generale). **D.Lgs. 502/1992 e 229/1999**: aziendalizzazione, regionalizzazione, accreditamento. **Riforma del Titolo V (2001)**: la tutela della salute è competenza concorrente Stato-Regioni.'],
      { h: 'Livelli di governo' }, [{ table: { head: ['Livello', 'Ruolo'], rows: [['**Stato** (Ministero della Salute, ISS, AIFA, AGENAS)', 'Fissa i **LEA**, la programmazione e il Piano sanitario nazionale, la sicurezza dei farmaci e la prevenzione'], ['**Regione** (es. Regione Toscana)', 'Organizza e finanzia i servizi, programma, accredita; designa le Aziende sanitarie'], ['**Azienda USL/ASL** (es. Azienda USL Toscana Centro)', 'Eroga assistenza territoriale e ospedaliera tramite distretti, dipartimenti e presidi'], ['**Azienda ospedaliero-universitaria** (es. AOU Careggi)', 'Ospedale di alta specializzazione integrato con l’Università: assistenza, didattica e ricerca'], ['**Distretto**', 'Articolazione territoriale della ASL: cure primarie, specialistica ambulatoriale, consultori, ADI, salute mentale, Case della Comunità']] } }],
      { h: 'Livelli Essenziali di Assistenza (LEA)' }, ['Tre macro-livelli: **prevenzione collettiva e sanità pubblica** (vaccinazioni, screening, sicurezza alimentare), **assistenza distrettuale** (medicina di base, specialistica, farmaceutica, domiciliare, residenziale, salute mentale), **assistenza ospedaliera**. Aggiornati con il DPCM 12/01/2017.', '**Medico di medicina generale** e **pediatra di libera scelta**: scelti dall’assistito; **continuità assistenziale** (guardia medica) e numero **116117** per le cure non urgenti; **112/118** per le emergenze.'],
      { h: 'Partecipazione e costi' }, ['**Ticket** per prestazioni specialistiche e farmaci con **esenzioni** per reddito, età e patologia (es. 048 per i tumori); **DRG**: sistema di classificazione dei ricoveri per il finanziamento a prestazione.', 'Rete **emergenza-urgenza**: 118, pronto soccorso, centri specializzati (stroke, trauma, cardiologia interventistica: hub & spoke).'],
      { h: 'Il contesto del corso' }, ['L’AOU Careggi e le Aziende USL toscane sono sedi di tirocinio dei corsi di laurea in Infermieristica dell’Università di Firenze; i tirocinanti seguono le regole di sicurezza, privacy e responsabilità del servizio ospitante ([[tirocinio-guida]]).']],
    ['management-organizzazione', 'assistenza-territoriale', 'igiene-sanita-pubblica', 'calendario-vaccinale', 'tirocinio-guida'], ['mds-pnpv', 'dm77-2022']),

  // ------------------------------------------------------------------ IGIENE, MICROBIOLOGIA, PATOLOGIA GENERALE
  C('igiene-sanita-pubblica', 'Igiene e sanità pubblica: prevenzione, sorveglianza, screening', ['igiene', 'sanità pubblica', 'prevenzione primaria', 'prevenzione secondaria', 'prevenzione terziaria', 'screening', 'sorveglianza epidemiologica', 'notifica obbligatoria', 'malattie infettive notifica classi', 'catena epidemiologica', 'modalità di trasmissione', 'isolamento quarantena', 'disinfezione sterilizzazione', 'sterilizzazione autoclave', 'ICA', 'sicurezza alimentare', 'HACCP', 'legionella', 'rifiuti', 'One Health', 'Piano nazionale della prevenzione'], 'Prevenzione', 'L’igiene studia come prevenire le malattie nella popolazione: dalla catena di trasmissione delle infezioni alle vaccinazioni, agli screening e alla sorveglianza.',
    [{ h: 'Livelli di prevenzione' }, ['**Primaria**: evita l’insorgenza (vaccini, stili di vita, sicurezza). **Secondaria**: diagnosi precoce (screening). **Terziaria**: limita le conseguenze (riabilitazione, prevenzione delle recidive).', '**Promozione della salute** e **educazione sanitaria**: [[educazione-terapeutica]].'],
      { h: 'Catena epidemiologica e trasmissione' }, ['Anelli: **agente** → **serbatoio** (uomo, animale, ambiente) → **porta di uscita** → **via di trasmissione** → **porta d’ingresso** → **ospite suscettibile**; si spezza almeno un anello.', 'Vie: **diretta** (contatto, goccioline, sessuale, verticale madre-figlio) e **indiretta** (veicoli comuni: acqua, alimenti; vettori: zanzare, zecche; aria; oggetti).', 'Termini: **endemia, epidemia, pandemia**; **periodo di incubazione**; **numero di riproduzione R₀**; **immunità di gregge** (soglia di copertura vaccinale, es. ~95% per il morbillo).'],
      { h: 'Sorveglianza e notifica' }, ['Le malattie infettive sono a **notifica obbligatoria** con tempi differenziati (storicamente classi I–V secondo il DM 15/12/1990; il sistema è stato rivisto dal DM 7/3/2022 con il sistema PREMAL: verifica l’elenco vigente). Esempi di malattie da segnalare: colera, botulismo, poliomielite, morbillo, meningite, epatiti, tubercolosi, pertosse, AIDS, sifilide e altre IST, focolai. Il medico segnala al Dipartimento di prevenzione della ASL; l’infermiere contribuisce con osservazione e segnalazione al medico.', 'Sorveglianza speciale: IST (ISS), HIV, influenza (InfluNet), arbovirosi, antibiotico-resistenza (AR-ISS), ICA (SPIN-UTI e studi di prevalenza ECDC).'],
      { h: 'Sterilizzazione, disinfezione, antisepsi' }, ['**Pulizia** (rimozione dello sporco) precede sempre disinfezione e sterilizzazione. **Disinfezione**: riduce i microrganismi (livelli basso, intermedio, alto). **Sterilizzazione**: elimina ogni forma microbica, spore comprese: **autoclave a vapore** (121 °C o 134 °C con pressione) è il metodo più usato; gas (ossido di etilene, plasma) per materiali termosensibili; indicatori chimici e biologici di controllo; confezioni integre e scadenza.', '**Classificazione di Spaulding** dei dispositivi: critici (sterili), semicritici (disinfezione di alto livello), non critici (pulizia/disinfezione).', 'Antisettici: clorexidina, iodopovidone, alcol; igiene delle mani ([[igiene-mani]]); [[tecnica-asettica]].'],
      { h: 'Screening organizzati in Italia' }, ['Mammella, cervice uterina, colon-retto: gratuiti per fasce di età nelle ASL ([[tumori-solidi]]); screening neonatali (metabolico, uditivo, visivo, cardiopatie) e dell’infezione in gravidanza.'],
      { h: 'Ambiente e alimenti' }, ['**HACCP** per la sicurezza alimentare; **Legionella** (acqua calda e impianti, ricoveri di pazienti fragili); qualità dell’aria e dell’acqua; rifiuti sanitari ([[rifiuti-sanitari]]); approccio **One Health** (salute umana, animale, ambientale).']],
    ['isolamento-precauzioni', 'calendario-vaccinale', 'ica', 'igiene-mani', 'tecnica-asettica', 'statistica-epidemiologia', 'ssn-organizzazione', 'microbiologia-generale'], ['ecdc', 'mds-pnpv', 'who-hh']),

  C('microbiologia-generale', 'Microbiologia: batteri, virus, funghi e parassiti', ['batteri', 'virus', 'funghi', 'protozoi', 'colorazione di Gram', 'gram positivi', 'gram negativi', 'antibiotico-resistenza', 'MRSA', 'ESBL', 'CRE', 'antibiogramma', 'coltura', 'flora batterica', 'microbiota', 'patogenicità', 'tossine', 'spore', 'prioni', 'sepsi microbiologia', 'ciclo del virus', 'antibiotici meccanismo'], 'Scienze di base', 'Elenco ragionato dei microrganismi di interesse sanitario, come si classificano e perché l’antibiotico-resistenza è una minaccia mondiale.',
    [{ h: 'Classificazione' }, [{ table: { head: ['Gruppo', 'Caratteristiche', 'Esempi'], rows: [['**Batteri Gram positivi**', 'Parete spessa, colorazione viola', '*Staphylococcus aureus* (MRSA), *Streptococcus* (pneumoniae, pyogenes), *Enterococcus*, *Clostridium* (tetani, botulinum, difficile), *Listeria*'], ['**Batteri Gram negativi**', 'Parete sottile con membrana esterna (endotossina), colorazione rosa', '*E. coli*, *Klebsiella*, *Pseudomonas*, *Acinetobacter*, *Salmonella*, *Neisseria* (meningitidis, gonorrhoeae), *Haemophilus*'], ['Bacilli acido-alcol resistenti', 'Parete cerosa, crescita lenta', '*Mycobacterium tuberculosis*'], ['Batteri senza parete / intracellulari', 'Poco colorabili', '*Mycoplasma*, *Chlamydia*, *Legionella*, *Rickettsia*'], ['**Virus**', 'DNA o RNA, parassiti obbligati, nessun antibiotico efficace', 'HIV, epatiti A-B-C, herpes, influenza, SARS-CoV-2, HPV, morbillo, rotavirus'], ['**Funghi**', 'Lieviti e muffe', '*Candida*, *Aspergillus*, dermatofiti'], ['**Protozoi e elminti**', 'Parassiti unicellulari e vermi', '*Plasmodium*, *Trichomonas*, *Giardia*, *Toxoplasma*, ossiuri, *Echinococcus*'], ['**Artropodi**', 'Ectoparassiti', 'Scabbia, pidocchi, zecche']] } }],
      { h: 'Concetti chiave' }, ['**Flora residente** (cute, intestino, vagina) protegge; diventa patogena in sedi sterili o in immunodepressione. **Patogenicità** e **virulenza**; **tossine** (esotossine proteiche; endotossine = LPS dei Gram negativi: shock settico).', '**Spore** (Clostridium, Bacillus) resistono a calore e disinfettanti: servono acqua e sapone per *C. difficile* ([[clostridioides-difficile]]).', '**Colorazione di Gram** e **colture** con **antibiogramma** (sensibile, intermedio, resistente) guidano la terapia; le colture vanno raccolte **prima** dell’antibiotico quando possibile ([[emocoltura-prelievo]]).'],
      { h: 'Antibiotico-resistenza' }, ['Meccanismi: enzimi (β-lattamasi, ESBL, carbapenemasi), pompe di efflusso, modifica del bersaglio. Germi allarmanti: **MRSA**, **enterobatteri produttori di carbapenemasi (CRE/KPC)**, *Acinetobacter*, *Pseudomonas* multiresistenti, VRE ([[mdro]]).', 'Cause: uso eccessivo e improprio di antibiotici (umano e veterinario). Contrasto: **stewardship antibiotica**, igiene delle mani, precauzioni di isolamento ([[isolamento-precauzioni]]), vaccini, diagnosi rapide.'],
      { h: 'Antibiotici (meccanismi, senza dosi)' }, ['Parete (β-lattamici, glicopeptidi), sintesi proteica (macrolidi, tetracicline, aminoglicosidi), acidi nucleici (fluorochinoloni, rifampicina), metabolismo (sulfamidici). Antivirali e antimicotici: [[antivirali]], [[antimicotici-antiparassitari]]. Classi e precauzioni: [[antibiotici]].']],
    ['antibiotici', 'mdro', 'clostridioides-difficile', 'isolamento-precauzioni', 'igiene-sanita-pubblica', 'sistema-immunitario']),

  C('patologia-generale', 'Patologia generale: infiammazione, riparazione, necrosi, neoplasie', ['patologia generale', 'infiammazione acuta', 'infiammazione cronica', 'granuloma', 'flogosi', 'necrosi', 'apoptosi', 'atrofia', 'ipertrofia', 'iperplasia', 'metaplasia', 'displasia', 'neoplasia benigna maligna', 'metastasi', 'cancerogenesi', 'edema', 'trombosi', 'embolia', 'infarto', 'ischemia', 'ipossia', 'shock', 'febbre', 'amiloidosi', 'riparazione'], 'Scienze di base', 'La patologia generale spiega i meccanismi comuni a molte malattie: danno cellulare, infiammazione, alterazioni circolatorie e crescita tumorale.',
    [{ h: 'Danno cellulare' }, ['Cause: ipossia, agenti fisici, chimici, infettivi, immunitari, genetici, nutrizionali. Il danno può essere **reversibile** (tumefazione, steatosi) o **irreversibile**: **necrosi** (morte accidentale con infiammazione: coagulativa, colliquativa, caseosa, gangrena) o **apoptosi** (morte programmata fisiologica, senza infiammazione).', '**Adattamenti**: atrofia (riduzione di volume), ipertrofia (aumento delle dimensioni delle cellule), iperplasia (aumento numerico), **metaplasia** (cambio di tipo cellulare, es. fumo), **displasia** (alterazione precancerosa).'],
      { h: 'Infiammazione' }, ['Segni cardinali (Celso e Virchow): **rubor, tumor, calor, dolor, functio laesa**.', '**Acuta**: vasodilatazione, aumento della permeabilità (essudato), arrivo di neutrofili; mediatori (istamina, bradichinina, prostaglandine, citochine). Esiti: risoluzione, guarigione con cicatrice, ascesso, cronicizzazione. **Cronica**: macrofagi, linfociti, fibrosi; **granuloma** (es. tubercolosi, sarcoidosi). **Risposta di fase acuta**: febbre, leucocitosi, ↑PCR e VES ([[risposta-infiammatoria]], [[pcr]]).'],
      { h: 'Riparazione' }, ['Rigenerazione (tessuti labili) o sostituzione con **tessuto di granulazione e cicatrice** ([[cicatrizzazione]]); fattori che la ostacolano: infezione, diabete, malnutrizione, farmaci (corticosteroidi), cattiva perfusione, tabagismo.'],
      { h: 'Alterazioni emodinamiche' }, ['**Edema**: eccesso di liquido interstiziale (↑pressione idrostatica, ↓pressione oncotica, ↑permeabilità, ostruzione linfatica: [[edema]]). **Trombosi** (triade di Virchow: stasi, danno endoteliale, ipercoagulabilità), **embolia**, **infarto** (necrosi ischemica), **shock** ([[shock]]), **emorragia**, **iperemia**.'],
      { h: 'Neoplasie' }, ['**Benigne** (crescita lenta, capsulate, non metastatizzano) vs **maligne** (infiltrano, metastatizzano per via linfatica, ematica, per contiguità); denominazioni: carcinoma (epitelio), sarcoma (connettivo), linfoma/leucemia (sangue). Basi: mutazioni di **oncogeni** e **geni oncosoppressori** (p53), perdita dell’apoptosi, angiogenesi. **Gradazione** (differenziazione) e **stadiazione TNM** ([[tumori-solidi]]). Cancerogeni: fumo, UV, radiazioni, virus (HPV, HBV, EBV), sostanze chimiche.'],
      { h: 'Febbre' }, ['Aumento del “set point” ipotalamico da pirogeni (IL-1, IL-6, TNF) e prostaglandine E₂: [[termoregolazione]], [[febbre]].']],
    ['risposta-infiammatoria', 'cicatrizzazione', 'tumori-solidi', 'edema', 'shock', 'istologia-tessuti', 'sistema-immunitario']),

  // ------------------------------------------------------------------ METODOLOGIA, LINGUA, INFORMATICA
  C('ricerca-ebp', 'Ricerca infermieristica ed Evidence-Based Practice (EBP)', ['EBP', 'evidence based practice', 'evidence based nursing', 'quesito PICO', 'PICO', 'PubMed', 'Cochrane', 'revisione sistematica', 'metanalisi', 'GRADE', 'linee guida', 'JBI', 'CASP', 'studio qualitativo', 'fenomenologia', 'grounded theory', 'tesi di laurea', 'bibliografia', 'plagio', 'impact factor', 'abstract', 'IMRaD', 'revisione della letteratura', 'MeSH'], 'Metodologia', 'Usare le migliori prove disponibili, insieme all’esperienza e alle preferenze del paziente, è il cuore dell’EBP; serve per le linee guida, per la pratica e per la tesi.',
    [{ h: 'EBP in cinque passi' }, [{ ol: ['**Formula il quesito** con il formato **PICO**: Patient/problema, Intervention, Comparison, Outcome (es. “Nei pazienti con catetere venoso centrale (P), la clorexidina (I) rispetto allo iodopovidone (C) riduce le batteriemie (O)?”).', '**Cerca** le prove nelle banche dati (PubMed/MEDLINE con **MeSH**, CINAHL, Cochrane Library, Embase), nei siti di linee guida (SNLG-ISS, NICE, JBI) con operatori booleani (AND, OR, NOT) e filtri.', '**Valuta criticamente** qualità e applicabilità (checklist CASP, JBI, AMSTAR per le revisioni; strumento GRADE per la forza delle raccomandazioni).', '**Applica** alla pratica insieme a esperienza clinica e preferenze del paziente.', '**Valuta** l’esito e aggiorna.'] }],
      { h: 'Gerarchia delle prove (dal più forte)' }, ['Revisioni sistematiche e metanalisi di RCT → trial randomizzati controllati (RCT) → studi di coorte → caso-controllo → serie di casi → opinione di esperti. Le linee guida solide integrano più livelli ([[statistica-epidemiologia]]).'],
      { h: 'Ricerca qualitativa' }, ['Esplora esperienze e significati (interviste, focus group): fenomenologia, grounded theory, etnografia. Criteri di rigore: credibilità, trasferibilità, affidabilità, confermabilità; saturazione dei dati.'],
      { h: 'Etica della ricerca' }, ['Approvazione del **comitato etico**, consenso informato, riservatezza dei dati (GDPR), conflitto di interessi, onestà (no plagio, no falsificazione); stili di citazione (Vancouver) ([[bioetica]]).'],
      { h: 'La tesi di laurea' }, ['Struttura di un elaborato **IMRaD**: Introduzione, Metodi, Risultati e Discussione; abstract, parole chiave, bibliografia aggiornata. Per le tesi sperimentali: protocollo, campione, strumenti, analisi. Per le **revisioni della letteratura**: strategia di ricerca riproducibile, criteri di inclusione ed esclusione, diagramma PRISMA. Cerca un relatore e un argomento nell’area di tirocinio e assistenza ([[prova-finale-abilitazione]]).']],
    ['statistica-epidemiologia', 'bioetica', 'prova-finale-abilitazione', 'informatica-sanitaria', 'inglese-medico'], ['iss-snlg', 'nice-ng']),

  C('inglese-medico', 'Inglese scientifico e medico per l’infermiere', ['inglese', 'English for nursing', 'terminologia inglese', 'glossario italiano inglese', 'abstract in inglese', 'leggere un articolo scientifico', 'comunicare con paziente straniero', 'ICN', 'checklist', 'handover'], 'Metodologia', 'Quasi tutta la letteratura scientifica è in inglese: conoscere i termini chiave serve per gli esami (lingua inglese), per la tesi e per lavorare all’estero.',
    [{ h: 'Glossario essenziale' }, [{ table: { head: ['Italiano', 'English'], rows: [['infermiere', 'nurse (registered nurse, RN)'], ['paziente / ricovero / dimissione', 'patient / admission / discharge'], ['segni vitali', 'vital signs'], ['pressione arteriosa / frequenza cardiaca', 'blood pressure / heart rate'], ['frequenza respiratoria / saturazione', 'respiratory rate / oxygen saturation'], ['dolore (scala)', 'pain (scale)'], ['ferita / medicazione', 'wound / dressing'], ['catetere venoso periferico', 'peripheral venous catheter (PVC / cannula)'], ['prelievo di sangue', 'blood draw / venepuncture'], ['iniezione intramuscolare / sottocutanea', 'intramuscular / subcutaneous injection'], ['terapia / prescrizione', 'treatment / prescription'], ['effetto collaterale', 'side effect / adverse effect'], ['allergia', 'allergy'], ['consegne', 'handover (SBAR: Situation, Background, Assessment, Recommendation)'], ['cartella clinica', 'medical record / chart'], ['consenso informato', 'informed consent'], ['lesione da pressione', 'pressure injury / ulcer'], ['caduta', 'fall'], ['infezione correlata all’assistenza', 'healthcare-associated infection (HAI)'], ['igiene delle mani', 'hand hygiene'], ['sepsi', 'sepsis'], ['scompenso cardiaco', 'heart failure'], ['infarto', 'myocardial infarction (heart attack)'], ['ictus', 'stroke'], ['rianimazione cardiopolmonare', 'cardiopulmonary resuscitation (CPR)']] } }],
      { h: 'Frasi utili con pazienti stranieri' }, ['“I’m your nurse, my name is… How are you feeling?” · “Do you have any pain? On a scale from 0 to 10…” · “Are you allergic to any medication?” · “I’m going to take your blood pressure.” · “Please tell me if you feel dizzy.” · “Do you understand? Can you repeat it in your own words?” (teach-back) · “Do you need an interpreter?”'],
      { h: 'Leggere un articolo scientifico' }, ['Sezioni: Abstract, Introduction, Methods, Results, Discussion, Conclusions, References. Parole spia: **randomized controlled trial**, **cohort study**, **systematic review**, **confidence interval**, **p-value**, **sample size**, **inclusion/exclusion criteria**, **outcome**, **bias**, **limitations**.', 'Strategia: leggi titolo e abstract; poi metodi e risultati con attenzione; confronta con le conclusioni degli autori.'],
      { h: 'Sigle internazionali comuni' }, ['ICU (terapia intensiva), ED/ER (pronto soccorso), OR (sala operatoria), PRN (al bisogno), NPO (digiuno), BID/TID (due/tre volte al giorno): in Italia preferisci scritture complete e le sigle approvate dal servizio (Raccomandazione ministeriale n. 18) ([[sigle-abbreviazioni]]).']],
    ['ricerca-ebp', 'sigle-abbreviazioni', 'terminologia-medica', 'consegne-sbar']),

  C('informatica-sanitaria', 'Informatica sanitaria, cartella elettronica e sicurezza dei dati', ['informatica', 'cartella clinica elettronica', 'fascicolo sanitario elettronico', 'FSE', 'telemedicina', 'telemonitoraggio', 'teleconsulto', 'cybersecurity', 'password', 'phishing', 'ricetta dematerializzata', 'intelligenza artificiale in sanità', 'interoperabilità', 'HL7 FHIR', 'foglio di calcolo', 'Excel', 'Word', 'PowerPoint', 'backup', 'GDPR', 'spid', 'cie'], 'Metodologia', 'Strumenti digitali di uso quotidiano nelle strutture sanitarie e nello studio: cartella elettronica, FSE, telemedicina e regole di sicurezza informatica.',
    [{ h: 'Sistemi informativi' }, ['**Cartella clinica elettronica (CCE)** e **cartella infermieristica informatizzata**: dati strutturati, allarmi, tracciabilità; l’accesso con **credenziali personali** è una responsabilità professionale (mai condividere la password).', '**Fascicolo Sanitario Elettronico (FSE 2.0)**: raccoglie referti, lettere di dimissione, vaccinazioni, ricette; accessibile al cittadino con SPID/CIE; il consenso alla consultazione da parte dei professionisti segue le regole del Garante.', '**Ricetta dematerializzata**, **CUP**, **Tessera sanitaria**; interoperabilità con standard (HL7 FHIR).'],
      { h: 'Telemedicina' }, ['**Televisita, teleconsulto, telemonitoraggio, teleassistenza** (Linee di indirizzo nazionali 2020 e Indicazioni 2022): richiedono consenso, identificazione, privacy e infrastruttura; l’infermiere ha ruolo nel supporto all’uso dei dispositivi e nel monitoraggio ([[assistenza-territoriale]]).'],
      { h: 'Sicurezza informatica e privacy' }, ['Password lunghe e diverse, **autenticazione a due fattori**, blocco dello schermo, **phishing** (email e SMS ingannevoli), backup, aggiornamenti; non salvare dati di pazienti su dispositivi personali né inviarli con app non autorizzate; **GDPR**: minimizzazione, finalità, conservazione, diritti dell’interessato; violazione dei dati (**data breach**) da segnalare entro 72 ore dal titolare ([[privacy-segreto]]).'],
      { h: 'Strumenti per lo studio' }, ['Fogli di calcolo (tabelle, grafici, funzioni statistiche di base), videoscrittura per la tesi (stili, indice, riferimenti bibliografici con Zotero/Mendeley), presentazioni efficaci (pochi testi, immagini, fonti), ricerca in banche dati ([[ricerca-ebp]]).', '**Intelligenza artificiale**: utile per riassumere e studiare, ma può sbagliare: verifica sempre sulle fonti, non inserire dati di pazienti reali ([[assistente-ai-uso]]).']],
    ['privacy-segreto', 'ricerca-ebp', 'assistenza-territoriale', 'documentazione-infermieristica', 'assistente-ai-uso']),

  C('assistente-ai-uso', 'Usare bene l’assistente AI e gli strumenti di studio dell’app', ['assistente AI', 'riassunto', 'mappa concettuale', 'schema', 'infografica', 'quiz', 'flashcard', 'casi clinici', 'backup', 'modalità studio', 'come studiare'], 'Metodologia', 'Come sfruttare Punto Salute per studiare: schede, quiz, flashcard, casi clinici, riassunti e mappe generati dall’app e assistente (offline o con AI opzionale).',
    [{ h: 'Strumenti' }, [{ ul: ['**Schede** collegate tra loro: parti da una patologia e segui i link (anatomia → fisiologia → patologia → assistenza).', '**Riassunto, mappa concettuale, schema, infografica** (pulsanti sulle schede): generano materiale di ripasso scaricabile in PDF/PNG.', '**Quiz e flashcard** (Studio): ripetizione con spiegazioni e collegamenti alle schede.', '**Casi clinici**: genera nuovi casi, rifai o rivedi quelli già fatti.', '**Assistente**: risponde con le schede dell’app e, se attivi, con AI e ricerca web; **backup** cifrato di note, progressi e chiavi.'] }],
      { h: 'Metodo di studio suggerito' }, [{ ol: ['Prima **capisci** (anatomia e fisiologia → patologia → farmaci → assistenza), poi **memorizza** con richiamo attivo (quiz, flashcard).', '**Ripasso distanziato**: rivedi a 1, 3, 7, 21 giorni.', '**Collega** teoria e tirocinio: dopo un turno in reparto rileggi le schede delle patologie e delle procedure viste ([[tirocinio-guida]]).', 'Esercizi con **casi clinici** e piani assistenziali ([[processo-infermieristico]]).'] }],
      { h: 'Cautele' }, ['L’AI può sbagliare o inventare: verifica sulle fonti indicate nelle schede. Non inserire dati identificativi di pazienti reali. Le schede non sostituiscono libri, lezioni e docenti: **per l’esame vale il programma del corso**.']],
    ['percorso-laurea', 'tirocinio-guida', 'informatica-sanitaria', 'processo-infermieristico']),

  C('terminologia-medica', 'Terminologia medica: radici, prefissi e suffissi', ['terminologia medica', 'prefissi', 'suffissi', 'radici greche', 'radici latine', 'etimologia medica', '-ite', '-osi', '-oma', '-ectomia', '-tomia', '-stomia', '-scopia', 'emi-', 'ipo-', 'iper-', 'dis-', 'a-', 'tachi-', 'brady-'], 'Metodologia', 'Quasi tutti i termini medici nascono da radici greche e latine: conoscere i pezzi permette di capire parole nuove.',
    [{ h: 'Suffissi' }, [{ table: { head: ['Suffisso', 'Significato', 'Esempio'], rows: [['-ite', 'infiammazione', 'appendicite, epatite, gastrite'], ['-osi', 'condizione, processo (spesso non infiammatorio)', 'fibrosi, trombosi, cirrosi'], ['-oma', 'tumore', 'carcinoma, melanoma, linfoma'], ['-patia', 'malattia', 'cardiopatia, neuropatia'], ['-algia', 'dolore', 'cefalea, nevralgia, artralgia'], ['-emia', 'nel sangue', 'iperkaliemia, anemia, batteriemia'], ['-uria', 'nelle urine', 'ematuria, proteinuria, disuria'], ['-ectomia', 'asportazione chirurgica', 'appendicectomia, colecistectomia'], ['-tomia', 'incisione', 'laparotomia, tracheotomia'], ['-stomia', 'apertura/comunicazione artificiale', 'colostomia, gastrostomia, tracheostomia'], ['-scopia', 'osservazione con strumento', 'endoscopia, broncoscopia'], ['-grafia', 'registrazione/immagine', 'elettrocardiografia, radiografia'], ['-plastica', 'ricostruzione', 'angioplastica, rinoplastica'], ['-penia', 'carenza', 'leucopenia, piastrinopenia'], ['-cito, -blasto', 'cellula, cellula immatura', 'eritrocito, linfoblasto']] } }],
      { h: 'Prefissi' }, [{ table: { head: ['Prefisso', 'Significato', 'Esempio'], rows: [['a-, an-', 'mancanza', 'anuria, afasia, anemia'], ['dis-', 'difficoltà, alterazione', 'dispnea, disfagia'], ['ipo- / iper-', 'meno / più del normale', 'ipotensione / ipertensione'], ['tachi- / brady-', 'veloce / lento', 'tachicardia / bradicardia'], ['poli- / oligo-', 'molto / poco', 'poliuria / oliguria'], ['emi-', 'metà', 'emiparesi'], ['para-, tetra-', 'due arti / quattro arti', 'paraplegia, tetraplegia'], ['peri-, endo-, epi-', 'intorno, dentro, sopra', 'pericardite, endocardite, epidermide'], ['intra-, extra-', 'dentro / fuori', 'intravenoso, extracellulare'], ['sub-, sopra-', 'sotto / sopra', 'sottocutaneo, sopraclavicolare']] } }],
      { h: 'Radici di organi (esempi)' }, ['cardio- (cuore), pneumo-/pulmo- (polmone), nefro-/reno- (rene), epato- (fegato), gastro- (stomaco), entero- (intestino), neuro- (nervo), encefalo- (cervello), osteo- (osso), artro- (articolazione), mio- (muscolo), derma- (cute), emato- (sangue), cito- (cellula), ofta- (occhio), oto- (orecchio), rino- (naso), cisto- (vescica), colpo-/metro-/isteri- (utero e vagina), vaso/angio- (vasi).'],
      { h: 'Esercizio di decodifica' }, ['**Poliuria** = poli (molto) + uria (urine). **Gastrectomia** = gastro (stomaco) + ectomia (asportazione). **Leucopenia** = leuco (bianco) + penia (carenza).']],
    ['sigle-abbreviazioni', 'inglese-medico']),

  C('sigle-abbreviazioni', 'Sigle e abbreviazioni sanitarie (e quelle da evitare)', ['sigle mediche', 'abbreviazioni', 'sigle pericolose', 'raccomandazione 18', 'U unità', 'IU', 'qd', 'ISMP sigle', 'AO', 'PA FC FR', 'SpO2', 'DM', 'IMA'], 'Metodologia', 'Le abbreviazioni sono utili ma possono causare errori: usa solo sigle standard del servizio e scrivi per esteso le informazioni critiche (Raccomandazione ministeriale n. 18).',
    [{ h: 'Sigle di uso comune' }, [{ table: { head: ['Sigla', 'Significato'], rows: [['PA, FC, FR, SpO₂, TC', 'Pressione arteriosa, frequenza cardiaca, frequenza respiratoria, saturazione, temperatura corporea'], ['ECG, EEG, EMG, RX, TC, RM, ECO', 'Elettrocardiogramma, elettroencefalogramma, elettromiografia, radiografia, tomografia computerizzata, risonanza magnetica, ecografia'], ['EV, IM, SC, ID, PO, SL', 'Endovenoso, intramuscolare, sottocutaneo, intradermico, per os (orale), sublinguale'], ['CVP, CVC, PICC, SNG, PEG', 'Catetere venoso periferico, catetere venoso centrale, catetere centrale ad inserzione periferica, sondino nasogastrico, gastrostomia endoscopica percutanea'], ['IMA, SCA, FA, TVP, EP, BPCO, IRA, IRC, DM, IVU', 'Infarto miocardico acuto, sindrome coronarica acuta, fibrillazione atriale, trombosi venosa profonda, embolia polmonare, BPCO, insufficienza renale acuta/cronica, diabete mellito, infezione delle vie urinarie'], ['ICA, MDR, MRSA', 'Infezioni correlate all’assistenza, multiresistente, *S. aureus* meticillino-resistente'], ['DAE, BLS, ALS, RCP, PBLS', 'Defibrillatore automatico esterno, supporto vitale di base/avanzato, rianimazione cardiopolmonare, BLS pediatrico'], ['NPO, DNR, DAT', 'Digiuno (nulla per os), non rianimare, disposizioni anticipate di trattamento'], ['SBAR', 'Situation, Background, Assessment, Recommendation (consegne)'], ['ADL, IADL', 'Attività di base e strumentali della vita quotidiana']] } }],
      { h: 'Sigle da evitare (rischio di errore)' }, ['“**U**” per unità (può essere letta come 0 o 4): scrivi “unità”. “**µg**” (può essere letto mg): scrivi “mcg” o “microgrammi”. Zero finale (“5,0 mg” letto 50) e zero iniziale mancante (“.5 mg” letto 5): scrivi “5 mg” e “0,5 mg”. Sigle per farmaci (es. “MTX”, “MS”: confondibili), “qd/qod” (usa “ogni giorno/a giorni alterni”), “>” e “<” ambigui nelle prescrizioni. Vedi [[rischio-clinico]] e [[farmaci-principi]].'],
      { h: 'Buona pratica' }, ['Elenco di sigle approvate dall’azienda; mai inventare sigle in cartella; in caso di dubbio chiedi e scrivi per esteso ([[documentazione-infermieristica]]).']],
    ['rischio-clinico', 'farmaci-principi', 'documentazione-infermieristica', 'terminologia-medica']),

  // ------------------------------------------------------------------ FARMACOLOGIA E NUTRIZIONE
  C('farmacologia-generale', 'Farmacologia generale: farmacocinetica, farmacodinamica, reazioni avverse', ['farmacocinetica', 'farmacodinamica', 'ADME', 'assorbimento', 'distribuzione', 'metabolismo epatico', 'eliminazione renale', 'emivita', 'biodisponibilità', 'steady state', 'effetto di primo passaggio', 'CYP450', 'interazioni farmacologiche', 'reazioni avverse ADR', 'tipo A tipo B', 'farmacovigilanza', 'indice terapeutico', 'agonista antagonista', 'tolleranza', 'dipendenza', 'placebo', 'generici equivalenti', 'off-label', 'effetto collaterale', 'eccipienti', 'vie di somministrazione', 'dieci giusti'], 'Farmacologia', 'Come i farmaci si muovono nel corpo (farmacocinetica), come agiscono (farmacodinamica) e perché possono fare danni: base per capire le schede dei farmaci.',
    [{ h: 'Farmacocinetica (cosa fa il corpo al farmaco): ADME' }, [{ ul: ['**A**ssorbimento: dalla sede di somministrazione al sangue; dipende da via, forma farmaceutica, pH, cibo. **Biodisponibilità** = frazione che raggiunge la circolazione (100% per via endovenosa).', '**D**istribuzione: volume di distribuzione; legame alle proteine plasmatiche (albumina): il farmaco libero è quello attivo; barriere (emato-encefalica, placentare).', '**M**etabolismo: soprattutto epatico (enzimi del **citocromo P450**); **effetto di primo passaggio** epatico dopo la via orale (la via sublinguale e rettale in parte lo evitano); induttori/inibitori enzimatici causano interazioni.', '**E**liminazione: renale (filtrazione e secrezione), biliare, polmonare; **emivita** (tempo per dimezzare la concentrazione): dopo circa 4–5 emivite si raggiunge lo **steady state**.'] }, 'In **insufficienza renale o epatica** e nell’**anziano** l’eliminazione è ridotta: i farmaci si accumulano ([[invecchiamento-fisiologia]]).'],
      { h: 'Farmacodinamica (cosa fa il farmaco al corpo)' }, ['Legame a **recettori**: **agonista** (attiva), **antagonista** (blocca), agonista parziale. Altri bersagli: enzimi, canali ionici, trasportatori.', '**Dose-risposta**, **potenza** ed **efficacia**; **indice terapeutico** (rapporto tra dose tossica ed efficace): farmaci a basso indice (digossina, litio, aminoglicosidi, anticoagulanti, insulina) richiedono prelievi e controlli ([[livelli-farmaci]]).', '**Tolleranza**, **dipendenza**, **tachifilassi**, **sinergismo/antagonismo** tra farmaci.'],
      { h: 'Reazioni avverse (ADR) e interazioni' }, ['**Tipo A** (prevedibili, dose-dipendenti: es. ipoglicemia da insulina, sanguinamento da anticoagulanti). **Tipo B** (imprevedibili: allergie e idiosincrasie, es. anafilassi da penicillina).', '**Interazioni**: farmacocinetiche (assorbimento, enzimi) e farmacodinamiche (somma di effetti); alimenti (pompelmo, vitamina K), erbe (iperico).', '**Farmacovigilanza**: ogni operatore sanitario può segnalare una sospetta reazione avversa ad **AIFA** (Rete Nazionale di Farmacovigilanza).'],
      { h: 'Vie e forme' }, ['Enterale (orale, sublinguale, rettale, via sondino), parenterale (EV, IM, SC, ID), topica e transdermica, inalatoria: [[vie-somministrazione-non-parenterali]], [[terapia-ev]], [[terapia-im]], [[terapia-sc]]. Forme a **rilascio modificato** non vanno frantumate ([[farmaci-sng-peg]]).'],
      { h: 'Sicurezza della terapia' }, ['**Regola dei “giusti”** (almeno 5, spesso 10): giusto paziente, farmaco, dose, via, tempo, motivo, documentazione, diritto di rifiutare, risposta, educazione. Farmaci **LASA** (aspetto o suono simile) e **ad alto rischio** (ISMP): doppio controllo ([[rischio-clinico]]).', '**Riconciliazione** tra terapia domiciliare e ospedaliera ([[accoglienza-dimissione]]).', 'Generici (equivalenti): stesso principio attivo, bioequivalenza; **off-label**: uso fuori indicazione registrata, con responsabilità del prescrittore.'],
      { h: 'Nota' }, ['In Punto Salute non compaiono dosi: dosaggi e diluizioni = prescrizione + RCP AIFA + protocollo locale; per i calcoli usa i [[calc-dose|calcolatori]] con doppio controllo.']],
    ['farmaci-principi', 'livelli-farmaci', 'rischio-clinico', 'calc-dose', 'invecchiamento-fisiologia', 'terapia-ev'], ['aifa', 'ismp', 'mn-rac']),

  C('nutrizione-dietetica', 'Nutrizione e dietetica clinica', ['nutrizione', 'dietetica', 'alimentazione', 'LARN', 'dieta mediterranea', 'piramide alimentare', 'dieta ipoproteica', 'dieta iposodica', 'dieta senza glutine', 'dieta per diabetico', 'disfagia dieta', 'consistenze modificate', 'IDDSI', 'integratori', 'alimentazione dell’anziano', 'screening nutrizionale', 'NRS-2002', 'MUST', 'MNA', 'refeeding'], 'Prevenzione e assistenza', 'Fabbisogni, scelte alimentari e diete terapeutiche: ogni paziente va valutato dal punto di vista nutrizionale e l’infermiere promuove un’alimentazione adeguata.',
    [{ h: 'Riferimenti italiani' }, ['**LARN** (Livelli di Assunzione di Riferimento di Nutrienti ed energia, SINU): la **V revisione** è la più recente; indica fabbisogni medi, assunzioni raccomandate e porzioni standard; **Linee guida per una sana alimentazione** (CREA): verificare l’edizione in vigore (l’ultima completa risale al 2018, con revisione in corso).', '**Dieta mediterranea**: patrimonio UNESCO: cereali integrali, legumi, verdura e frutta, olio extravergine, pesce, frutta secca; poca carne rossa e processata, pochi dolci.'],
      { h: 'Valutazione nutrizionale' }, ['Anamnesi alimentare e perdita di peso, **BMI** ([[calc-bmi]]), circonferenze, appetito, deglutizione, capacità di alimentarsi; screening con **MUST**, NRS-2002 (ospedale), **MNA** (anziano) ([[must]]); esami (albumina, linfociti, prealbumina: poco specifici); segnala **malnutrizione** ([[malnutrizione]]).'],
      { h: 'Diete terapeutiche (principi)' }, [{ ul: ['**Diabete**: carboidrati distribuiti, preferire fibre e indice glicemico basso, nessun alimento “proibito” in assoluto ([[diabete-mellito]]).', '**Ipertensione e scompenso**: ridurre il sale (< 5 g/die; dieta DASH), controllo dei liquidi se prescritto ([[ipertensione-arteriosa]], [[scompenso-cardiaco]]).', '**Insufficienza renale**: controllo di proteine, potassio, fosforo, sodio e liquidi su indicazione del nefrologo/dietista ([[insufficienza-renale-cronica]]).', '**Epatopatia**: apporto proteico adeguato (non ridotto), pasti frequenti, sodio ridotto con ascite ([[cirrosi-epatica]]).', '**Celiachia**: dieta senza glutine a vita ([[celiachia]]).', '**Dislipidemie e obesità**: grassi saturi ridotti, deficit calorico graduale ([[dislipidemia]], [[obesita]]).', '**Disfagia**: consistenze modificate (scala internazionale **IDDSI**), addensanti, posizione e supervisione ([[disfagia]]).', '**Chirurgia**: percorsi ERAS (alimentazione precoce).'] }],
      { h: 'Nutrizione artificiale' }, ['Enterale ([[nutrizione-enterale]]) quando l’intestino funziona; parenterale ([[nutrizione-parenterale]]) se non è possibile; **rischio di rialimentazione** nei malnutriti gravi ([[disturbi-alimentari]]).'],
      { h: 'Assistenza ai pasti' }, ['Ambiente adatto, igiene delle mani e del cavo orale, posizione seduta, protesi e occhiali, porzioni appetibili, imbocco con calma, controllo dell’assunzione (annotare % consumata), segnali di aspirazione ([[rischio-aspirazione]]).']],
    ['malnutrizione', 'must', 'calc-bmi', 'nutrizione-enterale', 'nutrizione-parenterale', 'termoregolazione-bilancio-energetico', 'disfagia'], ['espen-en', 'espen-pn']),

  C('violenza-maltrattamento', 'Violenza di genere, maltrattamento di minori e anziani', ['violenza domestica', 'violenza sulle donne', 'maltrattamento minori', 'abuso sessuale', 'maltrattamento anziani', 'codice rosa', 'percorso rosa', '1522', '114', 'indicatori di maltrattamento', 'Codice Rosso', 'stalking', 'mutilazioni genitali femminili', 'sindrome del bambino scosso', 'tratta', 'segnalazione', 'violenza assistita'], 'Etica e diritto', 'Gli operatori sanitari sono spesso i primi a incontrare chi subisce violenza: riconoscere i segnali, accogliere in sicurezza e segnalare con le procedure corrette può cambiare una vita.',
    [{ h: 'Riconoscere' }, ['**Violenza di genere/domestica**: fisica, psicologica, sessuale, economica, stalking. Indizi: lesioni in sedi insolite o a vari stadi, spiegazioni incoerenti, ritardo nel cercare cure, accessi ripetuti, partner che non lascia sola la persona, ansia, depressione, disturbi del sonno, gravidanza non pianificata, ripetute IST.', '**Minori**: lesioni inspiegate (ecchimosi in sedi non protette, ustioni a stampo, fratture multiple e a diverse età), trascuratezza, disturbi del comportamento, regressione; **sindrome del bambino scosso** (emorragie retiniche e subdurali nel lattante). Abuso sessuale: segni genitali, IST, gravidanza, racconti.', '**Anziani**: lesioni, trascuratezza igienica e nutrizionale, farmaci inappropriati, abuso economico, isolamento; autore spesso un familiare o il caregiver.'],
      { h: 'Come comportarsi' }, [{ ol: ['Spazio **riservato**; parla da solo con la persona (partner o familiare fuori dalla stanza con un pretesto); linguaggio non giudicante.', 'Chiedi direttamente (“Qualcuno le fa del male?”) e ascolta, credi, riconosci che non è colpa sua.', 'Valuta il **rischio immediato** e la sicurezza; documenta in modo oggettivo con le parole della persona tra virgolette, fotografie con consenso, lesioni dettagliate (valore medico-legale).', 'Attiva il **percorso dedicato** del servizio (Pronto Soccorso “**Codice Rosa**”; équipe multidisciplinare, servizi sociali, centri antiviolenza).', 'Informa la persona su **1522** (numero antiviolenza e stalking, gratuito, 24 ore) e **114** (emergenza infanzia).'] }],
      { h: 'Obblighi di legge' }, ['**Obbligo di denuncia/referto** all’autorità giudiziaria per i reati procedibili d’ufficio (es. maltrattamenti in famiglia, violenza sessuale su minore, lesioni gravi) per pubblici ufficiali e incaricati di pubblico servizio; per le donne adulte in alcuni casi la querela è della persona (valutare con l’équipe e i servizi di consulenza). Per i **minori** la segnalazione alla Procura è doverosa ([[medicina-legale-diritto]]).', '**Codice Rosso** (L. 69/2019): procedure rapide per i reati di violenza domestica e di genere; **mutilazioni genitali femminili** vietate (L. 7/2006) con segnalazione.'],
      { h: 'Supporto dopo' }, ['Cure per lesioni, profilassi per IST e gravidanza (contraccezione d’emergenza: [[contraccettivi]]; PEP per HIV: [[prep-pep-hiv]]), supporto psicologico, centri antiviolenza, tutela del minore.']],
    ['medicina-legale-diritto', 'privacy-segreto', 'contraccettivi', 'prep-pep-hiv', 'sociologia-antropologia-salute']),
];
